#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
# SPDX-FileCopyrightText: 2026 Yu Sung Yeh
# run every suite once, save raw outputs to $OUT (default /tmp/shokai-suites), then split the counts core vs extension
# with scripts/suite-split.mjs. Local only: loopback HTTP on a free port, a throwaway state dir, nothing sent or deployed.
set -uo pipefail
ROOT=$(cd "$(dirname "$0")/.." && pwd); OUT=${OUT:-/tmp/shokai-suites}; rm -rf "$OUT"; mkdir -p "$OUT"; rc=0
echo "== engawa npm test (vectors, golden, scenarios, v0.2.8, v0.2.9 brand door, v0.2.10)"
(cd "$ROOT/reference/engawa" && SHOKAI_CHECK_LOG="$OUT/checks.jsonl" npm test > "$OUT/engawa.txt" 2>&1) || rc=1; tail -1 "$OUT/engawa.txt"
echo "== reference conformance (prototype)"
(cd "$ROOT/reference/prototype" && npm run conformance > "$OUT/reference.txt" 2>&1) || rc=1; tail -1 "$OUT/reference.txt"
echo "== trace-lint (core + extensions)"; node "$ROOT/tools/trace-lint.mjs" > "$OUT/trace-lint.txt" 2>&1 || rc=1; tail -1 "$OUT/trace-lint.txt"
echo "== trace-typecheck"; node "$ROOT/tools/trace-typecheck.mjs" > "$OUT/trace-typecheck.txt" 2>&1 || rc=1; tail -1 "$OUT/trace-typecheck.txt"
echo "== JSON Schema (generated from protocol-shapes.ts; golden-trace messages validate, broken controls fail)"; node "$ROOT/tools/schema/schema.mjs" --check > "$OUT/schema.txt" 2>&1 || rc=1; tail -1 "$OUT/schema.txt"
echo "== reference signing page (software authenticator, loopback)"; node "$ROOT/reference/signing-page/test/e2e.mjs" > "$OUT/signing-page.txt" 2>&1 || rc=1; tail -1 "$OUT/signing-page.txt"
echo "== reference signing page: a Shōkai host card (v0.4.0; needs packages/shokai built)"; ( [ -f "$ROOT/packages/shokai/dist/src/index.js" ] || npm --prefix "$ROOT/packages/shokai" run build >/dev/null ) && node "$ROOT/reference/signing-page/test/host-card.e2e.mjs" > "$OUT/signing-page-host-card.txt" 2>&1 || rc=1; tail -1 "$OUT/signing-page-host-card.txt"
echo "== reference signing page: a one-purchase raise (SIGNING.md §8, the figure cross-check)"; node "$ROOT/reference/signing-page/test/raise.mjs" > "$OUT/signing-page-raise.txt" 2>&1 || rc=1; tail -1 "$OUT/signing-page-raise.txt"
echo "== reference signing page: supported languages (SIGNING.md §7, English and Japanese, figures equivalence)"; node "$ROOT/reference/signing-page/test/language.mjs" > "$OUT/signing-page-language.txt" 2>&1 || rc=1; tail -1 "$OUT/signing-page-language.txt"
echo "== agent install harness (path B vs A on sample Express and Next sites; scripted agent, no model calls)"; node "$ROOT/tools/agent-install-harness/harness.mjs" > "$OUT/agent-install.txt" 2>&1 || rc=1; tail -1 "$OUT/agent-install.txt"
echo "== review 4 vectors (possession_proof_v05, must_understand, G1-v05: regenerated byte for byte)"; node "$ROOT/tools/gen-r4-vectors.mjs" --check || rc=1
echo "== byte-exact shokai/0.5 traces (G1 browse, relay refusal, allowance+hold)"; node "$ROOT/tools/gen-v05-byte-traces.mjs" --check || rc=1
echo "== minimal browse door (examples/minimal-browse-door: Core Door (browse) from SPEC.md alone, no SDK; loopback)"; node "$ROOT/examples/minimal-browse-door/check.mjs" > "$OUT/browse-door.txt" 2>&1 || rc=1; tail -1 "$OUT/browse-door.txt"
echo "== drop-in snippets (README and site section; loopback)"; node "$ROOT/examples/drop-in/snippets/check.mjs" > "$OUT/drop-in-snippets.txt" 2>&1 || rc=1; tail -1 "$OUT/drop-in-snippets.txt"
echo "== signing-page preview copy (deploy/sign-preview)"; node "$ROOT/deploy/sign-preview/build.mjs" --check || rc=1
echo "== sign.kigenka.com front, relay mode (deploy/sign-front, loopback only)"; ( node "$ROOT/deploy/sign-front/build.mjs" --check && node "$ROOT/deploy/sign-front/test.mjs" ) > "$OUT/sign-front.txt" 2>&1 || rc=1; tail -1 "$OUT/sign-front.txt"
echo "== sign.kigenka.com serverless (deploy/sign-serverless: its own tests, and the signing page e2e run against it, loopback only)"; ( node "$ROOT/deploy/sign-serverless/build.mjs" --check && node "$ROOT/deploy/sign-serverless/test.mjs" && cd "$ROOT" && SIGNING_SERVER=deploy/sign-serverless/local.mjs node reference/signing-page/test/e2e.mjs && SIGNING_SERVER=deploy/sign-serverless/local.mjs node reference/signing-page/test/host-card.e2e.mjs ) > "$OUT/sign-serverless.txt" 2>&1 || rc=1; grep -E "^(sign-serverless|signing page):" "$OUT/sign-serverless.txt"
echo "== SDK package and demo place (npm pack, install the packed file, local door only)"; ( T=$(mktemp -d) && cd "$ROOT/packages/shokai" && npm pack --silent --pack-destination "$T" >/dev/null && cd "$ROOT/deploy/demo-place" && npm install --no-save --no-audit --no-fund --silent "$T"/kigenka-shokai-*.tgz && node test.mjs ) > "$OUT/demo-place.txt" 2>&1 || rc=1; tail -1 "$OUT/demo-place.txt"
echo "== enforcement suite (tools/enforce: attacks on a real Lanternmoss door on 127.0.0.1; no AI, no outside network)"; node "$ROOT/tools/enforce/enforce.mjs" --quiet --json="$OUT/enforce.json" > "$OUT/enforce.txt" 2>&1 || rc=1; tail -1 "$OUT/enforce.txt"
echo "== P20 sketch (draft proposal, not normative)"; node "$ROOT/tools/p20-sketch.mjs" > "$OUT/p20.txt" 2>&1 || rc=1; tail -1 "$OUT/p20.txt"
echo "== P32 sketch (draft proposal, not normative: outside the setup)"; node "$ROOT/tools/p32-sketch.mjs" > "$OUT/p32.txt" 2>&1 || rc=1; tail -1 "$OUT/p32.txt"
echo "== P26 amendment A sketch (draft proposal, not normative: binding a door to its site; needs packages/shokai built)"; ( [ -f "$ROOT/packages/shokai/dist/src/discover.js" ] || npm --prefix "$ROOT/packages/shokai" run build >/dev/null ) && node "$ROOT/tools/p26-sketch.mjs" > "$OUT/p26.txt" 2>&1 || rc=1; tail -1 "$OUT/p26.txt"
echo "== links and version strings (the SPEC.md header's version)"; node "$ROOT/tools/check-links-versions.mjs" > "$OUT/check-links-versions.txt" 2>&1 || rc=1; tail -1 "$OUT/check-links-versions.txt"
if [ "${SHOKAI_SKIP_QUICKSTART:-}" = "1" ]; then echo "== QUICKSTART.md: SKIPPED (SHOKAI_SKIP_QUICKSTART=1; it needs the network for a fresh npm install)"; else
echo "== QUICKSTART.md as written (tools/verify-quickstart.sh: npm pack, fresh install, every expected output compared exactly)"; bash "$ROOT/tools/verify-quickstart.sh" > "$OUT/quickstart.txt" 2>&1 || { rc=1; echo "  quickstart: FAILED (see $OUT/quickstart.txt)"; }; tail -1 "$OUT/quickstart.txt"
fi
echo "== HTTP end to end (loopback, free port, throwaway state)"
PORT=$(node -e 'const s=require("net").createServer();s.listen(0,"127.0.0.1",()=>{console.log(s.address().port);s.close()})')
ST=$(mktemp -d); (cd "$ROOT/reference/engawa" && exec node dist/src/server.js --port=$PORT --state="$ST/state" --wire="$ST/wire" > "$OUT/server.txt" 2>&1) & SRV=$!; sleep 1.5
for t in http-e2e http-press http-msgid; do
  (cd "$ROOT/reference/engawa" && node dist/test/$t.js $PORT > "$OUT/$t.txt" 2>&1) || rc=1; echo "  $t: $(grep -c '^  PASS' "$OUT/$t.txt") pass, $(grep -c '^  FAIL' "$OUT/$t.txt") fail"
done
# v0.5.0 black-box checks (C230–C255) with the conformance runner against the reference host's v0.5.0 fixture place (mock money).
node "$ROOT/packages/shokai/dist/src/conformance/cli.js" "http://127.0.0.1:$PORT" --place fernwood-v05 --spend 6.00 --hold-grace 2 --host-console "$ST/state/console" --claim shop --evidence "$ROOT/reference/engawa/conformance-evidence.json" --accept-evidence-exec > "$OUT/blackbox-v050.txt" 2>&1 || rc=1
echo "  black-box (fernwood-v05): $(sed -n '/^core: v0.5.0/,/^  → /p' "$OUT/blackbox-v050.txt" | grep '^  → ' | sed 's/^  → //'); $(tail -1 "$OUT/blackbox-v050.txt")"
grep -E '^  (HOLDS|FAILS) ' "$OUT/blackbox-v050.txt" | sed 's/^/  claim shop (fernwood-v05):/'
echo "  Note: the suite-split 'core N/N' total later in this log is the in-process suite homes only. Official HTTP runner rows (including C300/C301) are reported in the black-box fernwood run above and are not added into that in-process total."
kill "$SRV" 2>/dev/null || true; wait "$SRV" 2>/dev/null; rm -rf "$ST"   # only the server this script started, by its pid
echo; node "$ROOT/tools/suite-split.mjs" "$OUT" || rc=1
exit $rc
